 install(id:string){const was=this.assembly.has(id);if(this.hangar||this.phase==='dead'||this.player.hp<=0||!this.assembly.install(id))return false;if(this.target&&(this.target===id||this.assembly.lockedBy(this.target)))this.target=undefined;this.scoreSupplies.receipt=undefined;this.fx({kind:'install',x:this.player.x,y:this.player.y,size:100,color:'#a9f3e5',life:.8});this.notice={title:was?'组件精校 +1':'新组件已装配',detail:id,time:2,icon:undefined};this.events.push({type:'upgrade',value:id});return true;}
